    /**
     * Full rescore from scratch (records sorted chronologically first).
     */
    func rescore(records: [FfiContestQsoInput]) 
    
    /**
     * Current score snapshot.
     */
    func scoreSnapshot()  -> FfiContestScore
    
    func setMyStation(station: FfiMyStation?) 
    
    /**
     * Received exchange from a prior QSO with this callsign, if any.
     */
    func suggestedExchange(callsign: String)  -> [String: String]?
    
}
