#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFieldStore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = FieldStore

    public static func lift(_ handle: UInt64) throws -> FieldStore {
        return FieldStore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: FieldStore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FieldStore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: FieldStore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFieldStore_lift(_ handle: UInt64) throws -> FieldStore {
    return try FfiConverterTypeFieldStore.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFieldStore_lower(_ value: FieldStore) -> UInt64 {
    return FfiConverterTypeFieldStore.lower(value)
}






/**
