// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceSdrAudioListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceSdrAudioListener = UniffiVTableCallbackInterfaceSdrAudioListener(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeSdrAudioListener.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface SdrAudioListener: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeSdrAudioListener.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface SdrAudioListener: handle missing in uniffiClone")
            }
        },
        onAudioFrame: { (
            uniffiHandle: UInt64,
            samples: RustBuffer,
            sMeter: UInt16,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
