    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceSpotEngineListener = UniffiVTableCallbackInterfaceSpotEngineListener(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeSpotEngineListener.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface SpotEngineListener: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeSpotEngineListener.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface SpotEngineListener: handle missing in uniffiClone")
