/**
 * The stats the apps display: totals, streak, activity calendar, per-mode.
 * Also the shape persisted as the offline cache.
 */
public struct FfiAmtStats: Equatable, Hashable {
    public var sessions: Int64
    public var answered: Int64
    public var correct: Int64
    /**
     * `correct / answered`, 0–1; `None` when nothing was answered.
     */
    public var accuracy: Double?
    public var practiceSeconds: Double
    /**
     * Fastest single recognition ever, ms.
     */
    public var bestTtrMs: Int64?
    public var streak: FfiAmtStreak
    /**
     * Practice days, ascending by day.
     */
    public var activity: [FfiAmtActivityDay]
    /**
     * Seconds at which levels 1–4 begin, e.g. `[1, 300, 900, 1800]`.
     */
    public var levelThresholds: [Int64]
    public var perMode: [FfiAmtModeStats]
    /**
     * When the stats last changed server-side, epoch ms.
     */
    public var updatedAt: Int64
    /**
     * When this snapshot was fetched, unix seconds.
     */
    public var fetchedAt: Int64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(sessions: Int64, answered: Int64, correct: Int64, 
        /**
         * `correct / answered`, 0–1; `None` when nothing was answered.
         */accuracy: Double?, practiceSeconds: Double, 
        /**
         * Fastest single recognition ever, ms.
         */bestTtrMs: Int64?, streak: FfiAmtStreak, 
        /**
         * Practice days, ascending by day.
         */activity: [FfiAmtActivityDay], 
        /**
         * Seconds at which levels 1–4 begin, e.g. `[1, 300, 900, 1800]`.
         */levelThresholds: [Int64], perMode: [FfiAmtModeStats], 
        /**
         * When the stats last changed server-side, epoch ms.
         */updatedAt: Int64, 
        /**
         * When this snapshot was fetched, unix seconds.
         */fetchedAt: Int64) {
        self.sessions = sessions
        self.answered = answered
        self.correct = correct
        self.accuracy = accuracy
        self.practiceSeconds = practiceSeconds
        self.bestTtrMs = bestTtrMs
        self.streak = streak
        self.activity = activity
        self.levelThresholds = levelThresholds
        self.perMode = perMode
        self.updatedAt = updatedAt
        self.fetchedAt = fetchedAt
    }

    

    
}

