/**
 * Raw wizard ingredients for a new session. Everything here is what the user
 * entered (base callsign, prefix, resolved suffix string, program set, raw
 * references, resolved grid, parsed frequency/power); this API owns the
 * normalization so both platforms produce an identical row.
 */
public struct FfiCreateSessionInput: Equatable, Hashable {
    /**
     * Operator base callsign (the settings default). Uppercased here.
     */
    public var baseCallsign: String
    /**
     * Optional prefix (e.g. `"W6"`), may be empty. Trimmed+uppercased here.
     */
    public var callsignPrefix: String
    /**
     * Resolved suffix string (`"P"`, `"M"`, `"MM"`, `"AM"`, or a custom value).
     * The suffix *enum* stays a UI concern; the host resolves it to a string,
     * which is then trimmed+uppercased and joined here.
     */
    public var suffix: String
    public var isClubStation: Bool
    /**
     * Club base callsign (used only when `is_club_station`). Trimmed+uppercased.
     */
    public var clubCallsignInput: String
    public var mode: String
    /**
     * Parsed frequency in **MHz** (host parses the text field this phase).
     */
    public var frequencyMhz: Double?
    public var programs: [String]
    public var parkReference: String?
    public var sotaReference: String?
    public var missionReference: String?
    public var wwffReference: String?
    /**
     * Grid, already resolved from caches/GPS by the host this phase. Empty ⇒
     * `None`; otherwise uppercased.
     */
    public var myGrid: String?
    /**
     * Validated power in watts (host parses/validates `[1, 1500]` this phase).
     */
    public var power: Int64?
    public var myRig: String?
    public var myAntenna: String?
    /**
     * CW key; kept only when `mode == "CW"`.
     */
    public var selectedKey: String?
    /**
     * Microphone; kept only when `mode` is a phone mode.
     */
    public var selectedMic: String?
    public var extraEquipment: String?
    public var attendees: String?
    public var isRove: Bool
    public var contestId: String?
    public var contestCategory: String?
    public var contestOverlayCategory: String?
    public var contestPower: String?
    public var contestBands: String?
    public var contestOperator: String?
    /**
     * Additional operator callsigns (multi-op). Uppercased+trimmed+deduped.
     */
    public var operatorCallsigns: [String]
    /**
     * Local FK to the selected radio `EquipmentItem` (for CAT auto-connect).
     */
    public var radioItemId: String?
    public var tota: FfiWizardTotaInput?
    /**
     * Override the generated id (lets the host keep one id across its SwiftData
     * mirror). `None` ⇒ a fresh lowercased UUID.
     */
    public var idOverride: String?
    /**
     * Override the `started_at` timestamp (unix seconds). `None` ⇒ now.
     */
    public var startedAtOverride: Int64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Operator base callsign (the settings default). Uppercased here.
         */baseCallsign: String, 
        /**
         * Optional prefix (e.g. `"W6"`), may be empty. Trimmed+uppercased here.
         */callsignPrefix: String = "", 
        /**
         * Resolved suffix string (`"P"`, `"M"`, `"MM"`, `"AM"`, or a custom value).
         * The suffix *enum* stays a UI concern; the host resolves it to a string,
         * which is then trimmed+uppercased and joined here.
         */suffix: String = "", isClubStation: Bool, 
        /**
         * Club base callsign (used only when `is_club_station`). Trimmed+uppercased.
         */clubCallsignInput: String = "", mode: String, 
        /**
         * Parsed frequency in **MHz** (host parses the text field this phase).
         */frequencyMhz: Double?, programs: [String], parkReference: String?, sotaReference: String?, missionReference: String?, wwffReference: String?, 
        /**
         * Grid, already resolved from caches/GPS by the host this phase. Empty ⇒
         * `None`; otherwise uppercased.
         */myGrid: String?, 
        /**
         * Validated power in watts (host parses/validates `[1, 1500]` this phase).
         */power: Int64?, myRig: String?, myAntenna: String?, 
        /**
         * CW key; kept only when `mode == "CW"`.
         */selectedKey: String?, 
        /**
         * Microphone; kept only when `mode` is a phone mode.
         */selectedMic: String?, extraEquipment: String?, attendees: String?, isRove: Bool, contestId: String?, contestCategory: String?, contestOverlayCategory: String?, contestPower: String?, contestBands: String?, contestOperator: String?, 
        /**
         * Additional operator callsigns (multi-op). Uppercased+trimmed+deduped.
         */operatorCallsigns: [String] = [], 
        /**
         * Local FK to the selected radio `EquipmentItem` (for CAT auto-connect).
         */radioItemId: String?, tota: FfiWizardTotaInput? = nil, 
        /**
         * Override the generated id (lets the host keep one id across its SwiftData
         * mirror). `None` ⇒ a fresh lowercased UUID.
         */idOverride: String? = nil, 
        /**
         * Override the `started_at` timestamp (unix seconds). `None` ⇒ now.
         */startedAtOverride: Int64? = nil) {
        self.baseCallsign = baseCallsign
        self.callsignPrefix = callsignPrefix
        self.suffix = suffix
        self.isClubStation = isClubStation
        self.clubCallsignInput = clubCallsignInput
        self.mode = mode
        self.frequencyMhz = frequencyMhz
        self.programs = programs
        self.parkReference = parkReference
        self.sotaReference = sotaReference
        self.missionReference = missionReference
        self.wwffReference = wwffReference
        self.myGrid = myGrid
        self.power = power
        self.myRig = myRig
        self.myAntenna = myAntenna
        self.selectedKey = selectedKey
        self.selectedMic = selectedMic
        self.extraEquipment = extraEquipment
        self.attendees = attendees
        self.isRove = isRove
        self.contestId = contestId
        self.contestCategory = contestCategory
        self.contestOverlayCategory = contestOverlayCategory
        self.contestPower = contestPower
        self.contestBands = contestBands
        self.contestOperator = contestOperator
        self.operatorCallsigns = operatorCallsigns
        self.radioItemId = radioItemId
        self.tota = tota
        self.idOverride = idOverride
        self.startedAtOverride = startedAtOverride
    }

    

    
}

