 * Input for `SatelliteApi.build_doppler_schedule` — one pass, one
 * transponder. Steps must be multiples of 10 Hz.
 */
public struct FfiDopplerScheduleInput: Equatable, Hashable {
    public var noradId: UInt32
    public var observer: FfiObserver
    public var aosEpoch: Int64
    public var losEpoch: Int64
    /**
     * Transponder downlink center, Hz.
     */
    public var downlinkHz: UInt64
    /**
     * Transponder uplink center, Hz; None = downlink-only tracking.
     */
    public var uplinkHz: UInt64?
    public var downlinkStepHz: UInt32
    public var uplinkStepHz: UInt32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(noradId: UInt32, observer: FfiObserver, aosEpoch: Int64, losEpoch: Int64, 
        /**
         * Transponder downlink center, Hz.
         */downlinkHz: UInt64, 
        /**
         * Transponder uplink center, Hz; None = downlink-only tracking.
         */uplinkHz: UInt64?, downlinkStepHz: UInt32, uplinkStepHz: UInt32) {
        self.noradId = noradId
        self.observer = observer
        self.aosEpoch = aosEpoch
        self.losEpoch = losEpoch
        self.downlinkHz = downlinkHz
        self.uplinkHz = uplinkHz
        self.downlinkStepHz = downlinkStepHz
        self.uplinkStepHz = uplinkStepHz
