/**
 * Everything `log_qso` needs that the store + the active log don't already
 * carry: the contact fields, the host-resolved station-profile fields, and the
 * per-service "is configured" flags. Mirrors the `ActivityLogManager.logQSO`
 * parameter list plus the cached service configuration.
 */
public struct FfiLogQsoInput: Equatable, Hashable {
    /**
     * The active log to log into. A hunter QSO is linked to it via
     * `logging_session_id` and flagged `is_activity_log_qso`.
     */
    public var logId: String
    public var callsign: String
    public var band: String
    public var mode: String
    /**
     * Frequency in **MHz** (matches `QSO.frequency`); persisted as `freq_khz`.
     */
    public var frequencyMhz: Double?
    /**
     * RST sent — defaults to `"599"` in the iOS form.
     */
    public var rstSent: String
    /**
     * RST received — defaults to `"599"` in the iOS form.
     */
    public var rstReceived: String
    public var theirGrid: String?
    public var theirPark: String?
    public var sotaRef: String?
    public var notes: String?
    public var name: String?
    public var state: String?
    public var country: String?
    /**
     * Station-profile power (watts), resolved host-side from `StationProfile`.
     */
    public var power: Int64?
    /**
     * Station-profile rig, resolved host-side.
     */
    public var myRig: String?
    /**
     * Station-profile name, resolved host-side.
     */
    public var stationProfileName: String?
    /**
     * Whether QRZ upload is configured (Keychain check, host-side).
     */
    public var uploadQrz: Bool
    /**
     * Whether LoFi is device-linked (host-side). Preserved for parity; LoFi does
     * not use `ServicePresence` (`supports_upload == false`), so this is a no-op.
     */
    public var uploadLofi: Bool
    /**
     * Whether ClubLog credentials exist (host-side). Same no-op caveat as LoFi.
     */
    public var uploadClublog: Bool
    /**
     * Daily QSO goal (0 = disabled). Drives one-shot `daily_goal_reached`.
     */
    public var dailyGoal: Int64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The active log to log into. A hunter QSO is linked to it via
         * `logging_session_id` and flagged `is_activity_log_qso`.
         */logId: String, callsign: String, band: String, mode: String, 
        /**
         * Frequency in **MHz** (matches `QSO.frequency`); persisted as `freq_khz`.
         */frequencyMhz: Double?, 
        /**
         * RST sent — defaults to `"599"` in the iOS form.
         */rstSent: String, 
        /**
         * RST received — defaults to `"599"` in the iOS form.
         */rstReceived: String, theirGrid: String?, theirPark: String?, sotaRef: String?, notes: String?, name: String?, state: String?, country: String?, 
        /**
         * Station-profile power (watts), resolved host-side from `StationProfile`.
         */power: Int64?, 
        /**
         * Station-profile rig, resolved host-side.
         */myRig: String?, 
        /**
         * Station-profile name, resolved host-side.
         */stationProfileName: String?, 
        /**
         * Whether QRZ upload is configured (Keychain check, host-side).
         */uploadQrz: Bool, 
        /**
         * Whether LoFi is device-linked (host-side). Preserved for parity; LoFi does
         * not use `ServicePresence` (`supports_upload == false`), so this is a no-op.
         */uploadLofi: Bool, 
        /**
         * Whether ClubLog credentials exist (host-side). Same no-op caveat as LoFi.
         */uploadClublog: Bool, 
        /**
         * Daily QSO goal (0 = disabled). Drives one-shot `daily_goal_reached`.
         */dailyGoal: Int64) {
        self.logId = logId
        self.callsign = callsign
        self.band = band
        self.mode = mode
        self.frequencyMhz = frequencyMhz
        self.rstSent = rstSent
        self.rstReceived = rstReceived
        self.theirGrid = theirGrid
        self.theirPark = theirPark
        self.sotaRef = sotaRef
        self.notes = notes
        self.name = name
        self.state = state
        self.country = country
        self.power = power
        self.myRig = myRig
        self.stationProfileName = stationProfileName
        self.uploadQrz = uploadQrz
        self.uploadLofi = uploadLofi
        self.uploadClublog = uploadClublog
        self.dailyGoal = dailyGoal
    }

    

    
}

