/**
 * The result of logging a hunter QSO: the persisted row, the refreshed today
 * stats, and whether this QSO is the one that *exactly* hit the daily goal.
 */
public struct FfiLogQsoResult: Equatable, Hashable {
    public var qso: FfiQso
    public var today: FfiTodayStats
    /**
     * `true` only on the QSO whose logging makes the count equal the daily goal
     * (fires once, mirroring `dailyGoalReached`). Always `false` when the goal
     * is disabled (0).
     */
    public var dailyGoalReached: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(qso: FfiQso, today: FfiTodayStats, 
        /**
         * `true` only on the QSO whose logging makes the count equal the daily goal
         * (fires once, mirroring `dailyGoalReached`). Always `false` when the goal
         * is disabled (0).
         */dailyGoalReached: Bool) {
        self.qso = qso
        self.today = today
        self.dailyGoalReached = dailyGoalReached
    }

    

    
}

