        self.myCallsign = myCallsign
        self.myGrid = myGrid
        self.mode = mode
        self.frequencyMhz = frequencyMhz
        self.satName = satName
        self.startedAtEpoch = startedAtEpoch
        self.endedAtEpoch = endedAtEpoch
    }

    

    
}

