/**
 * Per-contact inputs to `log_qso`. Everything the session itself supplies
 * (frequency/mode/park/WWFF/power/rig/callsign/grid/qsoComment/stationCallsign)
 * is read from the stored session; this carries the contact fields, the
 * optional per-QSO overrides, and the "is this service configured" booleans.
 */
public struct FfiSessionLogInput: Equatable, Hashable {
    public var sessionId: String
    public var callsign: String
    public var rstSent: String
    public var rstReceived: String
    public var theirGrid: String?
    public var theirPark: String?
    public var notes: String?
    public var name: String?
    public var qth: String?
    public var state: String?
    public var country: String?
    public var theirLicenseClass: String?
    public var aoaCode: String?
    public var callsignChangeNote: String?
    /**
     * Quick-entry frequency override in **MHz**; falls back to the session.
     */
    public var frequencyOverrideMhz: Double?
    /**
     * Quick-entry mode override; falls back to the session mode.
     */
    public var modeOverride: String?
    /**
     * Unix-seconds timestamp override; defaults to now.
     */
    public var timestampOverride: Int64?
    /**
     * Contest fields (the `isContest` branch of `logQSO`): stamped verbatim
     * onto the QSO when the session is a contest. All default `None` so
     * non-contest callers are unchanged.
     */
    public var contestName: String?
    public var contestSerialSent: Int64?
    public var contestSerialReceived: Int64?
    /**
     * Space-joined sent exchange tokens.
     */
    public var contestExchangeSent: String?
    /**
     * Space-joined received exchange tokens.
     */
    public var contestExchangeReceived: String?
    /**
     * ADIF SAT_NAME — satellite short name (e.g. "AO-91"). Set by the satellite
     * quick-log flow; `None` for terrestrial QSOs.
     */
    public var satName: String?
    /**
     * ADIF PROP_MODE — always "SAT" when `sat_name` is set.
     */
    public var propMode: String?
    public var uploadQrz: Bool
    /**
     * Whether POTA upload is configured. Only routed when the session is a POTA
     * activation.
     */
    public var uploadPota: Bool
    public var uploadLofi: Bool
    public var uploadClublog: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(sessionId: String, callsign: String, rstSent: String, rstReceived: String, theirGrid: String?, theirPark: String?, notes: String?, name: String?, qth: String?, state: String?, country: String?, theirLicenseClass: String?, aoaCode: String?, callsignChangeNote: String?, 
        /**
         * Quick-entry frequency override in **MHz**; falls back to the session.
         */frequencyOverrideMhz: Double?, 
        /**
         * Quick-entry mode override; falls back to the session mode.
         */modeOverride: String?, 
        /**
         * Unix-seconds timestamp override; defaults to now.
         */timestampOverride: Int64?, 
        /**
         * Contest fields (the `isContest` branch of `logQSO`): stamped verbatim
         * onto the QSO when the session is a contest. All default `None` so
         * non-contest callers are unchanged.
         */contestName: String? = nil, contestSerialSent: Int64? = nil, contestSerialReceived: Int64? = nil, 
        /**
         * Space-joined sent exchange tokens.
         */contestExchangeSent: String? = nil, 
        /**
         * Space-joined received exchange tokens.
         */contestExchangeReceived: String? = nil, 
        /**
         * ADIF SAT_NAME — satellite short name (e.g. "AO-91"). Set by the satellite
         * quick-log flow; `None` for terrestrial QSOs.
         */satName: String? = nil, 
        /**
         * ADIF PROP_MODE — always "SAT" when `sat_name` is set.
         */propMode: String? = nil, uploadQrz: Bool, 
        /**
         * Whether POTA upload is configured. Only routed when the session is a POTA
         * activation.
         */uploadPota: Bool, uploadLofi: Bool, uploadClublog: Bool) {
        self.sessionId = sessionId
        self.callsign = callsign
        self.rstSent = rstSent
        self.rstReceived = rstReceived
        self.theirGrid = theirGrid
        self.theirPark = theirPark
        self.notes = notes
        self.name = name
        self.qth = qth
        self.state = state
        self.country = country
        self.theirLicenseClass = theirLicenseClass
        self.aoaCode = aoaCode
        self.callsignChangeNote = callsignChangeNote
        self.frequencyOverrideMhz = frequencyOverrideMhz
        self.modeOverride = modeOverride
        self.timestampOverride = timestampOverride
        self.contestName = contestName
        self.contestSerialSent = contestSerialSent
        self.contestSerialReceived = contestSerialReceived
        self.contestExchangeSent = contestExchangeSent
        self.contestExchangeReceived = contestExchangeReceived
        self.satName = satName
        self.propMode = propMode
        self.uploadQrz = uploadQrz
        self.uploadPota = uploadPota
        self.uploadLofi = uploadLofi
        self.uploadClublog = uploadClublog
    }

    

    
}

