    /**
     * Result of the active band-scope query, when one is set.
     */
    public var allowedSpotIds: [String]?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Monotonic publish counter; equal generations = identical data.
         */generation: UInt64, spots: [FfiEnrichedSpot], counts: [FfiSourceCount], errors: [FfiSourceError], 
        /**
         * Unix epoch seconds of the last completed poll (0 = never).
         */lastRefresh: Int64, 
        /**
         * Result of the active band-scope query, when one is set.
         */allowedSpotIds: [String]?) {
        self.generation = generation
        self.spots = spots
        self.counts = counts
        self.errors = errors
        self.lastRefresh = lastRefresh
        self.allowedSpotIds = allowedSpotIds
    }

    

    
}

