 * `loggerDefault*` keys (the iOS `@AppStorage` surface). Every field is
 * optional so a fresh install returns an all-empty snapshot.
 */
public struct FfiWizardDefaults: Equatable, Hashable {
    public var mode: String?
    /**
     * Stored as text (the raw power field), matching iOS.
     */
    public var power: String?
    public var grid: String?
    public var radio: String?
    public var antenna: String?
    public var key: String?
    public var mic: String?
    /**
     * Program slugs (decoded from the sorted JSON blob / migrated legacy key).
     */
    public var programs: [String]
    public var parkReference: String?
    public var contestId: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(mode: String?, 
        /**
         * Stored as text (the raw power field), matching iOS.
         */power: String?, grid: String?, radio: String?, antenna: String?, key: String?, mic: String?, 
        /**
         * Program slugs (decoded from the sorted JSON blob / migrated legacy key).
         */programs: [String], parkReference: String?, contestId: String?) {
        self.mode = mode
        self.power = power
        self.grid = grid
        self.radio = radio
        self.antenna = antenna
        self.key = key
        self.mic = mic
        self.programs = programs
        self.parkReference = parkReference
        self.contestId = contestId
    }

    

    
}

