/**
 * Direct-copy TOTA fields, applied only when the derived activation type is
 * `tota` (the iOS `applyTOTAOptions` gate). The *derivations* that feed these
 * (winter auto-detect, ruck-weight autofill, QRP-from-power) stay host-side in
 * this phase, so every field here is a value the host already computed.
 */
public struct FfiWizardTotaInput: Equatable, Hashable {
    public var activationLatitude: Double?
    public var activationLongitude: Double?
    public var qrpActivation: Bool
    public var withPets: Bool
    public var withKids: Bool
    public var winlinkSent: Bool
    public var aprsSent: Bool
    public var varacSent: Bool
    public var adaptiveSport: Bool
    public var ruckWeightPounds: Double?
    /**
     * `"standard"` / `"mobile"`; `None` ⇒ standard.
     */
    public var totaCategoryRawValue: String?
    public var personalEffortFactor: Int64?
    /**
     * `0`/`1`/`None` — `None` means auto-detect (host or a later phase decides).
     */
    public var winterActivationOverride: Int64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(activationLatitude: Double?, activationLongitude: Double?, qrpActivation: Bool, withPets: Bool, withKids: Bool, winlinkSent: Bool, aprsSent: Bool, varacSent: Bool, adaptiveSport: Bool, ruckWeightPounds: Double?, 
        /**
         * `"standard"` / `"mobile"`; `None` ⇒ standard.
         */totaCategoryRawValue: String?, personalEffortFactor: Int64?, 
        /**
         * `0`/`1`/`None` — `None` means auto-detect (host or a later phase decides).
         */winterActivationOverride: Int64?) {
        self.activationLatitude = activationLatitude
        self.activationLongitude = activationLongitude
        self.qrpActivation = qrpActivation
        self.withPets = withPets
        self.withKids = withKids
        self.winlinkSent = winlinkSent
        self.aprsSent = aprsSent
        self.varacSent = varacSent
        self.adaptiveSport = adaptiveSport
        self.ruckWeightPounds = ruckWeightPounds
        self.totaCategoryRawValue = totaCategoryRawValue
        self.personalEffortFactor = personalEffortFactor
        self.winterActivationOverride = winterActivationOverride
    }

    

    
}

