/**
 * Type 2 Decode (`cw_net::wsjtx::Decode`).
 */
public struct FfiWsjtxDecode: Equatable, Hashable {
    public var id: String
    /**
     * `true` for a fresh decode, `false` when WSJT-X replays its
     * band-activity window.
     */
    public var new: Bool
    /**
     * UTC time of day of the decoded period as milliseconds since midnight;
     * `None` if WSJT-X sent a null `QTime`.
     */
    public var timeMs: UInt32?
    public var snr: Int32
    /**
     * Time offset from the period start, in seconds.
     */
    public var deltaTime: Double
    /**
     * Audio frequency offset from the dial frequency, in Hz.
     */
    public var deltaFrequency: UInt32
    /**
     * WSJT-X's one-character mode tag (e.g. `"~"` FT8, `"+"` FT4).
     */
    public var mode: String
    public var message: String
    public var lowConfidence: Bool?
    public var offAir: Bool?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, 
        /**
         * `true` for a fresh decode, `false` when WSJT-X replays its
         * band-activity window.
         */new: Bool, 
        /**
         * UTC time of day of the decoded period as milliseconds since midnight;
         * `None` if WSJT-X sent a null `QTime`.
         */timeMs: UInt32?, snr: Int32, 
        /**
         * Time offset from the period start, in seconds.
         */deltaTime: Double, 
        /**
         * Audio frequency offset from the dial frequency, in Hz.
         */deltaFrequency: UInt32, 
        /**
         * WSJT-X's one-character mode tag (e.g. `"~"` FT8, `"+"` FT4).
         */mode: String, message: String, lowConfidence: Bool?, offAir: Bool?) {
        self.id = id
        self.new = new
        self.timeMs = timeMs
        self.snr = snr
        self.deltaTime = deltaTime
        self.deltaFrequency = deltaFrequency
        self.mode = mode
        self.message = message
        self.lowConfidence = lowConfidence
        self.offAir = offAir
    }

    

    
}

