/**
 * A decoded WWFF Spotline spot with derived display fields.
 */
public struct FfiWwffSpot: Equatable, Hashable {
    /**
     * Row index assigned during HTML parsing (used as an opaque identifier).
     */
    public var id: Int64
    public var activator: String
    /**
     * WWFF reference, e.g. "KFF-1234".
     */
    public var reference: String
    public var referenceInfo: String?
    public var spotter: String
    /**
     * Frequency in MHz as a string, e.g. "14.244".
     */
    public var frequency: String
    public var mode: String
    /**
     * The raw "Info" cell from the HTML table; also used to detect RBN spots.
     */
    public var comments: String?
    /**
     * "RBN" when the spot was generated by an automated decoder, `None` otherwise.
     */
    public var source: String?
    /**
     * ISO-8601 UTC timestamp built from the Spotline "HH:MM" time column.
     */
    public var time: String
    /**
     * Frequency in kHz, or `None` if the frequency string is unparseable.
     */
    public var frequencyKhz: Double?
    /**
     * Unix epoch seconds parsed from `time`, or `None` if unparseable.
     */
    public var timestampEpochSeconds: Double?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Row index assigned during HTML parsing (used as an opaque identifier).
         */id: Int64, activator: String, 
        /**
         * WWFF reference, e.g. "KFF-1234".
         */reference: String, referenceInfo: String?, spotter: String, 
        /**
         * Frequency in MHz as a string, e.g. "14.244".
         */frequency: String, mode: String, 
        /**
         * The raw "Info" cell from the HTML table; also used to detect RBN spots.
         */comments: String?, 
        /**
         * "RBN" when the spot was generated by an automated decoder, `None` otherwise.
         */source: String?, 
        /**
         * ISO-8601 UTC timestamp built from the Spotline "HH:MM" time column.
         */time: String, 
        /**
         * Frequency in kHz, or `None` if the frequency string is unparseable.
         */frequencyKhz: Double?, 
        /**
         * Unix epoch seconds parsed from `time`, or `None` if unparseable.
         */timestampEpochSeconds: Double?) {
        self.id = id
        self.activator = activator
        self.reference = reference
        self.referenceInfo = referenceInfo
        self.spotter = spotter
        self.frequency = frequency
        self.mode = mode
        self.comments = comments
        self.source = source
        self.time = time
        self.frequencyKhz = frequencyKhz
        self.timestampEpochSeconds = timestampEpochSeconds
    }

    

    
}

