public enum CwError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Query(reason: String
    )
    case Store(reason: String
    )
    case Network(reason: String
    )
    case Auth(reason: String
    )
    case Crypto(reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CwError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCwError: FfiConverterRustBuffer {
    typealias SwiftType = CwError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CwError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Query(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Store(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Network(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Auth(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Crypto(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CwError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Query(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Store(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Network(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Auth(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Crypto(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCwError_lift(_ buf: RustBuffer) throws -> CwError {
    return try FfiConverterTypeCwError.lift(buf)
}

