    )
    case leftBandTooEarly(band: String, start: Int64, durationSeconds: Double, minimumSeconds: Double
    )





}

#if compiler(>=6)
extension FfiBandChangeViolation: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiBandChangeViolation: FfiConverterRustBuffer {
    typealias SwiftType = FfiBandChangeViolation

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiBandChangeViolation {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .tooManyChangesInClockHour(hourStart: try FfiConverterInt64.read(from: &buf), count: try FfiConverterInt64.read(from: &buf), limit: try FfiConverterInt64.read(from: &buf)
        )
        
        case 2: return .leftBandTooEarly(band: try FfiConverterString.read(from: &buf), start: try FfiConverterInt64.read(from: &buf), durationSeconds: try FfiConverterDouble.read(from: &buf), minimumSeconds: try FfiConverterDouble.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiBandChangeViolation, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .tooManyChangesInClockHour(hourStart,count,limit):
            writeInt(&buf, Int32(1))
            FfiConverterInt64.write(hourStart, into: &buf)
            FfiConverterInt64.write(count, into: &buf)
            FfiConverterInt64.write(limit, into: &buf)
            
        
        case let .leftBandTooEarly(band,start,durationSeconds,minimumSeconds):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(band, into: &buf)
            FfiConverterInt64.write(start, into: &buf)
            FfiConverterDouble.write(durationSeconds, into: &buf)
            FfiConverterDouble.write(minimumSeconds, into: &buf)
            
        }
    }
}


