// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * A computed stat value. Mirrors `cw_domain::brag_sheet::BragStatValue`, one
 * variant per case (UniFFI enums can't carry per-variant docs from the
 * domain type, so the shape is duplicated verbatim).
 */

public enum FfiBragStatValue: Equatable, Hashable {
    
    case count(value: Int64
    )
    case distance(km: Double
    )
    case duration(seconds: Double
    )
    case rate(value: Double, label: String
    )
    case contact(callsign: String, distanceKm: Double?, band: String?
    )
    case power(watts: Double, callsign: String, distanceKm: Double?, band: String?
    )
    case efficiency(wattsPerMile: Double, detail: String
    )
    case progress(current: Int64, total: Int64
    )
    case streak(current: Int64, longest: Int64
    )
    case bandTable(entries: [FfiBandTableEntry]
    )
    case dayOfWeek(day: String, count: Int64
    )
    case callsignCount(callsign: String, count: Int64
    )
    case timeOfDay(unixSeconds: Int64
    )
    case parkDetail(park: String, date: String?, count: Int64
    )
    case modeStreakList(entries: [FfiModeStreakEntry]
    )
    case wpm(words: Int64
    )
    case rst(value: String, detail: String?
    )
    case noData





}

#if compiler(>=6)
extension FfiBragStatValue: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiBragStatValue: FfiConverterRustBuffer {
    typealias SwiftType = FfiBragStatValue

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiBragStatValue {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .count(value: try FfiConverterInt64.read(from: &buf)
        )
        
        case 2: return .distance(km: try FfiConverterDouble.read(from: &buf)
        )
        
        case 3: return .duration(seconds: try FfiConverterDouble.read(from: &buf)
        )
        
        case 4: return .rate(value: try FfiConverterDouble.read(from: &buf), label: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .contact(callsign: try FfiConverterString.read(from: &buf), distanceKm: try FfiConverterOptionDouble.read(from: &buf), band: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 6: return .power(watts: try FfiConverterDouble.read(from: &buf), callsign: try FfiConverterString.read(from: &buf), distanceKm: try FfiConverterOptionDouble.read(from: &buf), band: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 7: return .efficiency(wattsPerMile: try FfiConverterDouble.read(from: &buf), detail: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .progress(current: try FfiConverterInt64.read(from: &buf), total: try FfiConverterInt64.read(from: &buf)
        )
        
        case 9: return .streak(current: try FfiConverterInt64.read(from: &buf), longest: try FfiConverterInt64.read(from: &buf)
        )
        
        case 10: return .bandTable(entries: try FfiConverterSequenceTypeFfiBandTableEntry.read(from: &buf)
        )
        
        case 11: return .dayOfWeek(day: try FfiConverterString.read(from: &buf), count: try FfiConverterInt64.read(from: &buf)
        )
        
        case 12: return .callsignCount(callsign: try FfiConverterString.read(from: &buf), count: try FfiConverterInt64.read(from: &buf)
        )
        
        case 13: return .timeOfDay(unixSeconds: try FfiConverterInt64.read(from: &buf)
        )
        
        case 14: return .parkDetail(park: try FfiConverterString.read(from: &buf), date: try FfiConverterOptionString.read(from: &buf), count: try FfiConverterInt64.read(from: &buf)
        )
        
        case 15: return .modeStreakList(entries: try FfiConverterSequenceTypeFfiModeStreakEntry.read(from: &buf)
        )
        
        case 16: return .wpm(words: try FfiConverterInt64.read(from: &buf)
        )
        
        case 17: return .rst(value: try FfiConverterString.read(from: &buf), detail: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 18: return .noData
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiBragStatValue, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .count(value):
            writeInt(&buf, Int32(1))
            FfiConverterInt64.write(value, into: &buf)
            
        
        case let .distance(km):
            writeInt(&buf, Int32(2))
            FfiConverterDouble.write(km, into: &buf)
            
        
        case let .duration(seconds):
            writeInt(&buf, Int32(3))
            FfiConverterDouble.write(seconds, into: &buf)
            
        
        case let .rate(value,label):
            writeInt(&buf, Int32(4))
            FfiConverterDouble.write(value, into: &buf)
            FfiConverterString.write(label, into: &buf)
            
        
        case let .contact(callsign,distanceKm,band):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(callsign, into: &buf)
            FfiConverterOptionDouble.write(distanceKm, into: &buf)
            FfiConverterOptionString.write(band, into: &buf)
            
        
        case let .power(watts,callsign,distanceKm,band):
            writeInt(&buf, Int32(6))
            FfiConverterDouble.write(watts, into: &buf)
            FfiConverterString.write(callsign, into: &buf)
            FfiConverterOptionDouble.write(distanceKm, into: &buf)
            FfiConverterOptionString.write(band, into: &buf)
            
        
        case let .efficiency(wattsPerMile,detail):
            writeInt(&buf, Int32(7))
            FfiConverterDouble.write(wattsPerMile, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .progress(current,total):
            writeInt(&buf, Int32(8))
            FfiConverterInt64.write(current, into: &buf)
            FfiConverterInt64.write(total, into: &buf)
            
        
        case let .streak(current,longest):
            writeInt(&buf, Int32(9))
            FfiConverterInt64.write(current, into: &buf)
            FfiConverterInt64.write(longest, into: &buf)
            
        
        case let .bandTable(entries):
            writeInt(&buf, Int32(10))
            FfiConverterSequenceTypeFfiBandTableEntry.write(entries, into: &buf)
            
        
        case let .dayOfWeek(day,count):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(day, into: &buf)
            FfiConverterInt64.write(count, into: &buf)
            
        
        case let .callsignCount(callsign,count):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(callsign, into: &buf)
            FfiConverterInt64.write(count, into: &buf)
            
        
        case let .timeOfDay(unixSeconds):
            writeInt(&buf, Int32(13))
            FfiConverterInt64.write(unixSeconds, into: &buf)
            
        
        case let .parkDetail(park,date,count):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(park, into: &buf)
            FfiConverterOptionString.write(date, into: &buf)
            FfiConverterInt64.write(count, into: &buf)
            
        
        case let .modeStreakList(entries):
            writeInt(&buf, Int32(15))
            FfiConverterSequenceTypeFfiModeStreakEntry.write(entries, into: &buf)
            
        
        case let .wpm(words):
            writeInt(&buf, Int32(16))
            FfiConverterInt64.write(words, into: &buf)
            
        
        case let .rst(value,detail):
            writeInt(&buf, Int32(17))
            FfiConverterString.write(value, into: &buf)
            FfiConverterOptionString.write(detail, into: &buf)
            
        
        case .noData:
            writeInt(&buf, Int32(18))
        
        }
    }
}


