// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What the host should do after a command runs. State changes are already
 * applied to cw-store; everything else is an intent the host carries out.
 */

public enum FfiCommandOutcome: Equatable, Hashable {
    
    /**
     * The session was changed (freq / mode / grid / callsign / note / metadata).
     * The host reflects `session`, shows `notice`, and runs its native side
     * effects: tune the radio to `tuned_frequency_mhz`, present the QSY-spot
     * sheet when `prompt_qsy_spot`, and post the initial spot when
     * `auto_spot_first_set`.
     */
    case sessionUpdated(session: FfiLoggingSession, notice: String, tunedFrequencyMhz: Double?, promptQsySpot: Bool, autoSpotFirstSet: Bool
    )
    /**
     * Log a one-off HUNT QSO (host routes it through the normal log path so
     * uploads / side effects stay consistent).
     */
    case logQso(input: FfiSessionLogInput
    )
    /**
     * Post a POTA/SOTA self-spot with this comment (host does the network call).
     */
    case postSpot(comment: String?
    )
    /**
     * Start a repeating self-spot timer (host owns the timer).
     */
    case startRepeatSpot(comment: String?, intervalMinutes: Int32
    )
    /**
     * Stop the repeating self-spot timer.
     */
    case stopRepeatSpot
    /**
     * Present a native panel.
     */
    case present(panel: FfiCommandPanel
    )
    /**
     * Show a toast (validation failures, "start a session first", etc.).
     */
    case message(level: FfiMessageLevel, text: String
    )





}

#if compiler(>=6)
extension FfiCommandOutcome: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiCommandOutcome: FfiConverterRustBuffer {
    typealias SwiftType = FfiCommandOutcome

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiCommandOutcome {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .sessionUpdated(session: try FfiConverterTypeFfiLoggingSession.read(from: &buf), notice: try FfiConverterString.read(from: &buf), tunedFrequencyMhz: try FfiConverterOptionDouble.read(from: &buf), promptQsySpot: try FfiConverterBool.read(from: &buf), autoSpotFirstSet: try FfiConverterBool.read(from: &buf)
        )
        
        case 2: return .logQso(input: try FfiConverterTypeFfiSessionLogInput.read(from: &buf)
        )
        
        case 3: return .postSpot(comment: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 4: return .startRepeatSpot(comment: try FfiConverterOptionString.read(from: &buf), intervalMinutes: try FfiConverterInt32.read(from: &buf)
        )
        
        case 5: return .stopRepeatSpot
        
        case 6: return .present(panel: try FfiConverterTypeFfiCommandPanel.read(from: &buf)
        )
        
        case 7: return .message(level: try FfiConverterTypeFfiMessageLevel.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiCommandOutcome, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .sessionUpdated(session,notice,tunedFrequencyMhz,promptQsySpot,autoSpotFirstSet):
            writeInt(&buf, Int32(1))
            FfiConverterTypeFfiLoggingSession.write(session, into: &buf)
            FfiConverterString.write(notice, into: &buf)
            FfiConverterOptionDouble.write(tunedFrequencyMhz, into: &buf)
            FfiConverterBool.write(promptQsySpot, into: &buf)
            FfiConverterBool.write(autoSpotFirstSet, into: &buf)
            
        
        case let .logQso(input):
            writeInt(&buf, Int32(2))
            FfiConverterTypeFfiSessionLogInput.write(input, into: &buf)
            
        
        case let .postSpot(comment):
            writeInt(&buf, Int32(3))
            FfiConverterOptionString.write(comment, into: &buf)
            
        
        case let .startRepeatSpot(comment,intervalMinutes):
            writeInt(&buf, Int32(4))
            FfiConverterOptionString.write(comment, into: &buf)
            FfiConverterInt32.write(intervalMinutes, into: &buf)
            
        
        case .stopRepeatSpot:
            writeInt(&buf, Int32(5))
        
        
        case let .present(panel):
            writeInt(&buf, Int32(6))
            FfiConverterTypeFfiCommandPanel.write(panel, into: &buf)
            
        
        case let .message(level,text):
            writeInt(&buf, Int32(7))
            FfiConverterTypeFfiMessageLevel.write(level, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        }
    }
}


