        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .reference(phase: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .literal(value: try FfiConverterInt64.read(from: &buf)
        )
        
        case 3: return .add(inputs: try FfiConverterSequenceTypeFfiContestAggregateOp.read(from: &buf)
        )
        
        case 4: return .multiply(inputs: try FfiConverterSequenceTypeFfiContestAggregateOp.read(from: &buf)
        )
        
