        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiContestAggregateOp, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .reference(phase):
            writeInt(&buf, Int32(1))
