public enum FfiContestScoringPhase: Equatable, Hashable {
    
    case perQso(id: String, description: String?, rules: [FfiContestScoringRule]
    )
    case multiplierCount(id: String, description: String?, source: String, 
        /**
         * True = per_band, false = per_contest.
         */perBand: Bool, includeZeroPointQsos: Bool
    )
    case aggregate(id: String, description: String?, operation: FfiContestAggregateOp
    )





}

#if compiler(>=6)
extension FfiContestScoringPhase: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiContestScoringPhase: FfiConverterRustBuffer {
    typealias SwiftType = FfiContestScoringPhase

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiContestScoringPhase {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .perQso(id: try FfiConverterString.read(from: &buf), description: try FfiConverterOptionString.read(from: &buf), rules: try FfiConverterSequenceTypeFfiContestScoringRule.read(from: &buf)
        )
        
        case 2: return .multiplierCount(id: try FfiConverterString.read(from: &buf), description: try FfiConverterOptionString.read(from: &buf), source: try FfiConverterString.read(from: &buf), perBand: try FfiConverterBool.read(from: &buf), includeZeroPointQsos: try FfiConverterBool.read(from: &buf)
        )
        
        case 3: return .aggregate(id: try FfiConverterString.read(from: &buf), description: try FfiConverterOptionString.read(from: &buf), operation: try FfiConverterTypeFfiContestAggregateOp.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiContestScoringPhase, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .perQso(id,description,rules):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(id, into: &buf)
            FfiConverterOptionString.write(description, into: &buf)
            FfiConverterSequenceTypeFfiContestScoringRule.write(rules, into: &buf)
            
        
        case let .multiplierCount(id,description,source,perBand,includeZeroPointQsos):
