/**
 * Day-scoped duplicate status of a callsign for the logger. Port of iOS
 * `CallsignDuplicateStatus`. Returned by [`FieldStore::duplicate_status`].
 */

public enum FfiDuplicateStatus: Equatable, Hashable {
    
    /**
     * First contact with this callsign today.
     */
    case firstContact
    /**
     * Worked today but the current band is unknown — informational only.
     */
    case previouslyWorked(previousBands: [String]
    )
    /**
     * Worked today on other band(s), not this one.
     */
    case newBand(previousBands: [String]
    )
    /**
     * Same band today, different mode family — a valid new QSO.
     */
    case newMode(band: String, previousModes: [String]
    )
    /**
     * Same band and equivalent mode today — a true dupe.
     */
    case duplicateBand(band: String, isPota: Bool
    )





}

#if compiler(>=6)
extension FfiDuplicateStatus: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiDuplicateStatus: FfiConverterRustBuffer {
    typealias SwiftType = FfiDuplicateStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiDuplicateStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .firstContact
        
        case 2: return .previouslyWorked(previousBands: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 3: return .newBand(previousBands: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 4: return .newMode(band: try FfiConverterString.read(from: &buf), previousModes: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 5: return .duplicateBand(band: try FfiConverterString.read(from: &buf), isPota: try FfiConverterBool.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiDuplicateStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .firstContact:
            writeInt(&buf, Int32(1))
        
        
        case let .previouslyWorked(previousBands):
            writeInt(&buf, Int32(2))
            FfiConverterSequenceString.write(previousBands, into: &buf)
            
        
        case let .newBand(previousBands):
            writeInt(&buf, Int32(3))
            FfiConverterSequenceString.write(previousBands, into: &buf)
            
        
        case let .newMode(band,previousModes):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(band, into: &buf)
            FfiConverterSequenceString.write(previousModes, into: &buf)
            
        
        case let .duplicateBand(band,isPota):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(band, into: &buf)
            FfiConverterBool.write(isPota, into: &buf)
            
        }
    }
}


