            writeInt(&buf, Int32(1))
            FfiConverterInt64.write(start, into: &buf)
            FfiConverterDouble.write(durationSeconds, into: &buf)
            FfiConverterDouble.write(minimumSeconds, into: &buf)
            
        
        case let .exceededMaxOnAirTime(actualSeconds,allowedSeconds):
            writeInt(&buf, Int32(2))
            FfiConverterDouble.write(actualSeconds, into: &buf)
            FfiConverterDouble.write(allowedSeconds, into: &buf)
            
        }
