// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * How SDR frequencies relate to RF.
 */

public enum FfiTuningMode: Equatable, Hashable {
    
    /**
     * SDR on the rig's IF output (K3: `if_hz` 8_215_000, `inverted` true).
     * `cal_hz_by_mode` keys are uppercase CAT modes or `"*"`.
     */
    case ifTap(ifHz: Double, inverted: Bool, loOffsetHz: Double, calHzByMode: [String: Double]
    )
    /**
     * SDR on the antenna; retuned to follow the VFO.
     */
    case directRf(loOffsetHz: Double
    )





}

#if compiler(>=6)
extension FfiTuningMode: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiTuningMode: FfiConverterRustBuffer {
    typealias SwiftType = FfiTuningMode

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiTuningMode {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .ifTap(ifHz: try FfiConverterDouble.read(from: &buf), inverted: try FfiConverterBool.read(from: &buf), loOffsetHz: try FfiConverterDouble.read(from: &buf), calHzByMode: try FfiConverterDictionaryStringDouble.read(from: &buf)
        )
        
        case 2: return .directRf(loOffsetHz: try FfiConverterDouble.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiTuningMode, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .ifTap(ifHz,inverted,loOffsetHz,calHzByMode):
            writeInt(&buf, Int32(1))
            FfiConverterDouble.write(ifHz, into: &buf)
            FfiConverterBool.write(inverted, into: &buf)
            FfiConverterDouble.write(loOffsetHz, into: &buf)
            FfiConverterDictionaryStringDouble.write(calHzByMode, into: &buf)
            
        
        case let .directRf(loOffsetHz):
            writeInt(&buf, Int32(2))
            FfiConverterDouble.write(loOffsetHz, into: &buf)
            
        }
    }
}


