// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * One decoded WSJT-X datagram (`cw_net::wsjtx::WsjtxMessage`). Message types
 * the decoder does not model surface as `Other` with their numeric type.
 */

public enum FfiWsjtxMessage: Equatable, Hashable {
    
    case heartbeat(heartbeat: FfiWsjtxHeartbeat
    )
    case status(status: FfiWsjtxStatus
    )
    case decode(decode: FfiWsjtxDecode
    )
    case qsoLogged(qso: FfiWsjtxQsoLogged
    )
    case loggedAdif(adif: FfiWsjtxLoggedAdif
    )
    /**
     * Type 6 — the client is shutting down.
     */
    case close(id: String
    )
    /**
     * Any other message type, payload skipped.
     */
    case other(kind: UInt32, id: String
    )





}

#if compiler(>=6)
extension FfiWsjtxMessage: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
