public struct FfiConverterTypeFfiWsjtxMessage: FfiConverterRustBuffer {
    typealias SwiftType = FfiWsjtxMessage

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiWsjtxMessage {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .heartbeat(heartbeat: try FfiConverterTypeFfiWsjtxHeartbeat.read(from: &buf)
        )
        
        case 2: return .status(status: try FfiConverterTypeFfiWsjtxStatus.read(from: &buf)
        )
        
        case 3: return .decode(decode: try FfiConverterTypeFfiWsjtxDecode.read(from: &buf)
        )
        
        case 4: return .qsoLogged(qso: try FfiConverterTypeFfiWsjtxQsoLogged.read(from: &buf)
        )
        
        case 5: return .loggedAdif(adif: try FfiConverterTypeFfiWsjtxLoggedAdif.read(from: &buf)
        )
        
        case 6: return .close(id: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .other(kind: try FfiConverterUInt32.read(from: &buf), id: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiWsjtxMessage, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .heartbeat(heartbeat):
            writeInt(&buf, Int32(1))
            FfiConverterTypeFfiWsjtxHeartbeat.write(heartbeat, into: &buf)
            
        
        case let .status(status):
            writeInt(&buf, Int32(2))
            FfiConverterTypeFfiWsjtxStatus.write(status, into: &buf)
            
        
        case let .decode(decode):
            writeInt(&buf, Int32(3))
            FfiConverterTypeFfiWsjtxDecode.write(decode, into: &buf)
            
        
        case let .qsoLogged(qso):
            writeInt(&buf, Int32(4))
            FfiConverterTypeFfiWsjtxQsoLogged.write(qso, into: &buf)
            
        
        case let .loggedAdif(adif):
            writeInt(&buf, Int32(5))
            FfiConverterTypeFfiWsjtxLoggedAdif.write(adif, into: &buf)
            
        
        case let .close(id):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .other(kind,id):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(kind, into: &buf)
            FfiConverterString.write(id, into: &buf)
            
        }
    }
}


