/**
 * Everything the WSJT-X surface can fail with. Import variants mirror
 * `cw_store::WsjtxImportError` one-to-one so hosts can switch on them.
 */
public enum WsjtxError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * `start` was called while a listener loop is already running on this
     * object; `stop()` first.
     */
    case AlreadyRunning
    /**
     * The UDP socket could not be bound (port in use, bad host, sandbox).
     */
    case Bind(address: String, reason: String
    )
    /**
     * A datagram handed to [`wsjtx_decode_datagram`] was not a WSJT-X message.
     */
    case Decode(reason: String
    )
    /**
     * `QSOLogged` carried neither a time-on nor a time-off.
     */
    case MissingTimestamp
    /**
     * `QSOLogged` carried a blank DX call.
     */
    case MissingCallsign
    /**
     * `LoggedADIF` parsed to zero records.
     */
    case NoAdifRecords
    /**
     * An ADIF record had no parsable `QSO_DATE` (+ `TIME_ON`).
     */
    case MissingAdifTimestamp(callsign: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension WsjtxError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeWsjtxError: FfiConverterRustBuffer {
    typealias SwiftType = WsjtxError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WsjtxError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .AlreadyRunning
        case 2: return .Bind(
            address: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Decode(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .MissingTimestamp
        case 5: return .MissingCallsign
        case 6: return .NoAdifRecords
        case 7: return .MissingAdifTimestamp(
            callsign: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WsjtxError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .AlreadyRunning:
            writeInt(&buf, Int32(1))
        
        
        case let .Bind(address,reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(address, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Decode(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .MissingTimestamp:
            writeInt(&buf, Int32(4))
        
        
        case .MissingCallsign:
            writeInt(&buf, Int32(5))
        
        
        case .NoAdifRecords:
            writeInt(&buf, Int32(6))
        
        
        case let .MissingAdifTimestamp(callsign):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(callsign, into: &buf)
            
        }
    }
}


